pub fn set_language(language: UiLanguage) {
    LANGUAGE.store(index(language) as u8, Ordering::Relaxed);
}

#[must_use]
pub fn current() -> UiLanguage {
    from_index(usize::from(LANGUAGE.load(Ordering::Relaxed)))
}

#[must_use]
pub fn text(key: Text) -> &'static str {
    text_for(current(), key)
}

#[must_use]
pub fn notice_text(notice: &UiNotice) -> String {
    notice_text_for(current(), notice)
}

#[must_use]
pub fn notice_text_for(language: UiLanguage, notice: &UiNotice) -> String {
    let text = |key| text_for(language, key);
    match notice {
        UiNotice::None => String::new(),
        UiNotice::FollowUpWaitingTurn => text(Text::WaitingFullTurn).to_owned(),
        UiNotice::FollowUpWaitingBoundary => text(Text::WaitingSafeBoundary).to_owned(),
        UiNotice::FollowUpEditedAfterFailure => text(Text::EditedRetryExplicit).to_owned(),
        UiNotice::FollowUpEditedPending => text(Text::EditedWaitingDelivery).to_owned(),
        UiNotice::FollowUpCancelledBeforeDelivery => text(Text::CancelledBeforeDelivery).to_owned(),
        UiNotice::FollowUpRetryQueued => text(Text::RetryWaitingFifo).to_owned(),
        UiNotice::FollowUpRetrySteer => text(Text::RetryActiveTurn).to_owned(),
        UiNotice::FollowUpDispatched => text(Text::DispatchedNextTurn).to_owned(),
        UiNotice::FollowUpDeliveredInsideTurn { turn_id } => {
            format!("{} #{turn_id}", text(Text::DeliveredInsideTurn))
        }
        UiNotice::FollowUpDeliveredAsTurn { turn_id } => turn_id.map_or_else(
            || text(Text::DeliveredAsFullTurn).to_owned(),
            |turn_id| format!("{} #{turn_id}", text(Text::DeliveredAsFullTurn)),
        ),
        UiNotice::FollowUpInterrupted => text(Text::DeliveryInterruptedRestart).to_owned(),
        UiNotice::FollowUpRecoveredPending => text(Text::RecoveredPendingRunNext).to_owned(),
        UiNotice::SideQuestionRunning => text(Text::ReadOnlySideRunning).to_owned(),
        UiNotice::SideAnswerProvisional => text(Text::ProvisionalSideAnswer).to_owned(),
        UiNotice::SideQuestionCancelled => text(Text::SideCancelledByUser).to_owned(),
        UiNotice::SideQuestionInterrupted => text(Text::SideInterruptedRestart).to_owned(),
        UiNotice::SideToolCallBlocked => text(Text::SideToolCallBlocked).to_owned(),
        UiNotice::SideAnswerEmpty => text(Text::SideAnswerEmpty).to_owned(),
        UiNotice::StaleUiAction => text(Text::StaleUiAction).to_owned(),
        UiNotice::TrustedDeploymentRequired => text(Text::TrustedDeploymentRequired).to_owned(),
        UiNotice::PersistenceBlocked => text(Text::PersistenceBlocked).to_owned(),
        UiNotice::DependencyFailure => text(Text::DependencyFailure).to_owned(),
        UiNotice::SteerRequiresActiveTurn => text(Text::SteerRequiresActiveTurn).to_owned(),
        UiNotice::LexicalFallback { detail } => {
            format!("{}: {detail}", text(Text::LexicalFallbackActive))
        }
        UiNotice::McpToolsReady { count } => format!("{count} {}", text(Text::ToolsReadyLabel)),
        UiNotice::SubagentMcpDisabled => text(Text::DisabledForRun).to_owned(),
        UiNotice::SubagentMcpStarting => format!("{} · MCP", text(Text::StartingStatus)),
        UiNotice::CodeIndexScanning { count } => {
            format!("{}: {count}", text(Text::ScanningCandidateFiles))
        }
        UiNotice::CodeIndexDisabled => text(Text::DisabledLabel).to_owned(),
        UiNotice::CodeIndexEmpty => text(Text::NoIndexedProjectFiles).to_owned(),
        UiNotice::CodeIndexLoading => text(Text::LoadingLabel).to_owned(),
        UiNotice::CodeIndexRefreshing => text(Text::SearchingRepoIndex).to_owned(),
        UiNotice::CodeIndexRebuilding => text(Text::FullRebuild).to_owned(),
        UiNotice::CodeIndexCancelling => format!(
            "{} · {}",
            text(Text::Cancel),
            text(Text::SearchingRepoIndex)
        ),
        UiNotice::CodeIndexCancelled => text(Text::Cancelled).to_owned(),
        UiNotice::CodeIndexReady => text(Text::Ready).to_owned(),
        UiNotice::CodeIndexProgress {
            scanned,
            reused,
            changed,
            skipped,
        } => format!(
            "{}: {scanned} · {}: {reused} · {}: {changed} · {}: {skipped}",
            text(Text::FilesLabel),
            text(Text::ReusedLabel),
            text(Text::ChangedLabel),
            text(Text::SkippedLabel)
        ),
        UiNotice::EmbeddingDisabled => text(Text::DisabledLabel).to_owned(),
        UiNotice::EmbeddingConfigured => text(Text::ReadyNextRequest).to_owned(),
        UiNotice::EmbeddingCancelling => text(Text::Cancel).to_owned(),
        UiNotice::EmbeddingCacheMissing => text(Text::NoIndexedProjectFiles).to_owned(),
        UiNotice::EmbeddingNoChunks => text(Text::NoIndexedProjectFiles).to_owned(),
        UiNotice::EmbeddingReady {
            count,
            reused,
            embedded,
        } => format!(
            "{}: {count} · {}: {reused} · {}: {embedded}",
            text(Text::ChunksLabel),
            text(Text::ReusedLabel),
            text(Text::EmbeddedLabel)
        ),
        UiNotice::EmbeddingPrivacyRefresh => text(Text::RefreshLabel).to_owned(),
        UiNotice::LspStarting => text(Text::StartingStatus).to_owned(),
        UiNotice::LspReady => text(Text::Ready).to_owned(),
        UiNotice::Stopped => text(Text::ClosedStatus).to_owned(),
        UiNotice::ExternalError { detail } => format!("{}: {detail}", text(Text::Failed)),
        UiNotice::Legacy { detail } => format!("{}: {detail}", text(Text::Status)),
    }
}

